-- Exclusivamente clone descartável. Há COMMIT para permitir teste entre sessões.
do $$begin if current_database()<>'sso_foto_cancel_0984_tmp' then raise exception 'banco_descartavel_exigido'; end if;end$$;
create extension if not exists pgtap with schema extensions;
create extension if not exists dblink with schema extensions;
set search_path=public,extensions;
select plan(8);
begin;
set local app.auvo_sync_write='true';
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values ('17985000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','corrida-cancelamento@example.test',crypt('x',gen_salt('bf')),'{}','{}',now(),now());
insert into config.usuarios(user_id,papel,nome,ativo) values ('17985000-0000-0000-0000-000000000001','colaborador','Corrida cancelamento',true);
insert into config.usuario_modulos(user_id,modulo,nivel) values ('17985000-0000-0000-0000-000000000001','pcm','escrita');
insert into pcm.clientes(id,nome,ativo,created_by) values ('17985000-0000-0000-0000-00000000000a','Cliente corrida',true,'17985000-0000-0000-0000-000000000001');
insert into config.sso_concessoes(usuario_id,acao,cliente_id) values ('17985000-0000-0000-0000-000000000001','cadastro.aprovar','17985000-0000-0000-0000-00000000000a');
insert into pcm.sso_levantamentos(id,cliente_id,origem,chave_origem,conteudo,criado_por) values ('17985000-0000-0000-0000-000000000021','17985000-0000-0000-0000-00000000000a','manual','corrida-cancelamento','[]','17985000-0000-0000-0000-000000000001');
insert into pcm.sso_levantamento_linhas(lote_id,chave,tipo,atributos) values ('17985000-0000-0000-0000-000000000021','a','sistema','{}');
update pcm.sso_ingestao_foto_gate set habilitado=true where id;
update pcm.sso_fotos_levantamento_gate set habilitado=true where id;
select pcm.sso_ingestao_foto_servico('reservar','17985000-0000-0000-0000-000000000001','17985000-0000-0000-0000-000000000041','17985000-0000-0000-0000-000000000021','a',repeat('a',64),null);
select pcm.sso_ingestao_foto_servico('reservar','17985000-0000-0000-0000-000000000001','17985000-0000-0000-0000-000000000042','17985000-0000-0000-0000-000000000021','a',repeat('b',64),null);
insert into storage.objects(id,bucket_id,name) select case when request_id='17985000-0000-0000-0000-000000000041' then '17985000-0000-0000-0000-000000000051'::uuid else '17985000-0000-0000-0000-000000000052'::uuid end,'sso-levantamento-fotos',nome from pcm.sso_ingestao_foto_reservas where request_id in ('17985000-0000-0000-0000-000000000041','17985000-0000-0000-0000-000000000042');
commit;
select extensions.dblink_connect('cancel_a','dbname='||current_database());
select extensions.dblink_connect('cancel_b','dbname='||current_database());
select extensions.dblink_exec('cancel_a','begin');
select extensions.dblink_exec('cancel_b','begin');
select extensions.dblink_exec('cancel_b','set local application_name = ''s178_cancel_b''');
select extensions.dblink_exec('cancel_a',$sql$set local request.jwt.claims='{"sub":"17985000-0000-0000-0000-000000000001","role":"authenticated","user_role":"colaborador"}'$sql$);
select extensions.dblink_exec('cancel_a','set local role authenticated');
select extensions.dblink_exec('cancel_b','set local role service_role');
select extensions.dblink_exec('cancel_b','set local app.auvo_sync_write = ''true''');
select r from extensions.dblink('cancel_a',$sql$select pcm.sso_cancelar_ingestao_foto('17985000-0000-0000-0000-00000000000a','17985000-0000-0000-0000-000000000041','17985000-0000-0000-0000-000000000021','a','Cancelamento concorrente')$sql$) as t(r jsonb);
select extensions.dblink_send_query('cancel_b',$sql$select pcm.sso_ingestao_foto_servico('confirmar','17985000-0000-0000-0000-000000000001','17985000-0000-0000-0000-000000000041','17985000-0000-0000-0000-000000000021','a',repeat('a',64),'17985000-0000-0000-0000-000000000051')$sql$);
select is(extensions.dblink_is_busy('cancel_b'),1,'confirmação concorre com cancelamento aberto');
do $$begin for i in 1..100 loop perform pg_stat_clear_snapshot();exit when exists(select 1 from pg_stat_activity where datname=current_database() and application_name='s178_cancel_b' and wait_event_type='Lock');perform pg_sleep(0.01);end loop;end$$;
select ok(exists(select 1 from pg_stat_activity where datname=current_database() and application_name='s178_cancel_b' and wait_event_type='Lock'),'confirmação espera bloqueio de cancelamento');
select extensions.dblink_exec('cancel_a','commit');
select count(*) from extensions.dblink_get_result('cancel_b',false) as t(r jsonb);
select matches(extensions.dblink_error_message('cancel_b'),'ingestao_cancelada','confirmação tardia recusada');
select count(*) from extensions.dblink_get_result('cancel_b',false) as t(r jsonb);
select extensions.dblink_exec('cancel_b','rollback');
select is((select count(*)::int from pcm.sso_fotos_levantamento where request_id='17985000-0000-0000-0000-000000000041'),0,'sem foto para reserva cancelada');
select extensions.dblink_exec('cancel_a','begin');
select extensions.dblink_exec('cancel_b','begin');
select extensions.dblink_exec('cancel_b','set local application_name = ''s178_cancel_b''');
select extensions.dblink_exec('cancel_a','set local role service_role');
select extensions.dblink_exec('cancel_a','set local app.auvo_sync_write = ''true''');
select extensions.dblink_exec('cancel_b',$sql$set local request.jwt.claims='{"sub":"17985000-0000-0000-0000-000000000001","role":"authenticated","user_role":"colaborador"}'$sql$);
select extensions.dblink_exec('cancel_b','set local role authenticated');
select r from extensions.dblink('cancel_a',$sql$select pcm.sso_ingestao_foto_servico('confirmar','17985000-0000-0000-0000-000000000001','17985000-0000-0000-0000-000000000042','17985000-0000-0000-0000-000000000021','a',repeat('b',64),'17985000-0000-0000-0000-000000000052')$sql$) as t(r jsonb);
select extensions.dblink_send_query('cancel_b',$sql$select pcm.sso_cancelar_ingestao_foto('17985000-0000-0000-0000-00000000000a','17985000-0000-0000-0000-000000000042','17985000-0000-0000-0000-000000000021','a','Cancelamento concorrente')$sql$);
select is(extensions.dblink_is_busy('cancel_b'),1,'cancelamento concorre com confirmação aberta');
do $$begin for i in 1..100 loop perform pg_stat_clear_snapshot();exit when exists(select 1 from pg_stat_activity where datname=current_database() and application_name='s178_cancel_b' and wait_event_type='Lock');perform pg_sleep(0.01);end loop;end$$;
select ok(exists(select 1 from pg_stat_activity where datname=current_database() and application_name='s178_cancel_b' and wait_event_type='Lock'),'cancelamento espera bloqueio de confirmação');
select extensions.dblink_exec('cancel_a','commit');
select count(*) from extensions.dblink_get_result('cancel_b',false) as t(r jsonb);
select matches(extensions.dblink_error_message('cancel_b'),'foto_ja_confirmada','cancelamento tardio recusado');
select count(*) from extensions.dblink_get_result('cancel_b',false) as t(r jsonb);
select extensions.dblink_exec('cancel_b','rollback');
select is((select count(*)::int from pcm.sso_fotos_levantamento where request_id='17985000-0000-0000-0000-000000000042'),1,'foto previamente confirmada é preservada');
select extensions.dblink_disconnect('cancel_a');select extensions.dblink_disconnect('cancel_b');
select * from finish();
